function CatDownloader:GetPosition(position)
    local index = math.floor(position % #POSITIONS)
    index = index == 0 and #POSITIONS or index
    return POSITIONS[index]
end

function CatDownloader:Awake()
    self.LoadingValue = KTool.GetComponent(self.LoadingValue.gameObject, typeof(CS.TMPro.TextMeshProUGUI))
    local imageLogo = self.LoadingBgGroup.transform.parent:Find("ImgLogo")
    if imageLogo then
        KTool.SetActive(imageLogo.gameObject, false)
    end
    --先不显示进度条
    for i = 1, IMAGE_COUNT do
        local bgImageKey = string.format("%s%d", LOADING_BG_PREFIX, i)
        local dotImageKey = string.format("%s%d", LOADING_DOT_PREFIX, i)
        self[bgImageKey] = self.LoadingBgGroup.transform:Find(bgImageKey)
        self[dotImageKey] = self.PageGroup.transform:Find(dotImageKey)
    end
end

