function CatDownloader:StartDownloader(jsonData)
    ---@type Engine.Lib.Updater.DownloadState
    local download = DownloadState(nil, ResourceModule.AppDataPath, "Download")
    local downloadMemberInfo = download:GetType()
    local property = downloadMemberInfo:GetProperty("PatchMd5S")
    local split = jsonData.split
    local isDelete = true
    if (KTool.UNITY_ANDROID() or KTool.UNITY_IOS()) and isNotNull(split) and table.count(split) > 0 and isNotNull(property) then
        local count = table.count(split)
        local spt = import('Frame.support')
        local patchDojos = spt.new_array(typeof(PatchDojo), count)
        for i = 1, table.count(split) do
            local dojo = PatchDojo()
            dojo.IsUpdate = false
            local split = jsonData.split
            local downloadInfo = split[i]
            dojo.url = downloadInfo.url
            if downloadInfo.xxh64 and not string.isEmpty(downloadInfo.xxh64) then
                dojo.md5 = downloadInfo.xxh64
            else
                dojo.md5 = downloadInfo.md5
            end
            dojo.size = checkNumber(downloadInfo.size)
            dojo.DecompressSize = checkNumber(downloadInfo.decompressSize)
            patchDojos[i - 1] = dojo
        end
        download.PatchMd5S = patchDojos

        local dojo = PatchDojo()
        dojo.IsUpdate = false
        dojo.url = jsonData.url
        if jsonData.xxh64 and not string.isEmpty(jsonData.xxh64) then
            dojo.md5 = jsonData.xxh64
        else
            dojo.md5 = jsonData.md5
        end
        download.PatchMd5 = dojo

        download.IsAutoState = true ---非自动状态有一处提示
        download.UseRetry = false ---使用重试机制
        isDelete = true
    else
        local count = 1
        local spt = import('Frame.support')
        local patchDojos = spt.new_array(typeof(PatchDojo), count)
        local dojo = PatchDojo()
        dojo.IsUpdate = false
        dojo.url = jsonData.url
        if jsonData.xxh64 and not string.isEmpty(jsonData.xxh64) then
            dojo.md5 = jsonData.xxh64
        else
            dojo.md5 = jsonData.md5
        end
        dojo.size = checkNumber(jsonData.size)
        local index = 0
        patchDojos[index] = dojo
        download.PatchMd5S = patchDojos
        isDelete = false
    end
    KTool.SetActive(self.LoadingSlider.gameObject, true)
    self.TxtLeft.text = localize('下载资源中...')
    local progressMap = {}
    download.ProgressCallback = function(DownloadedSize, TotalSize, speed)
        local size = DownloadedSize
        local Progress = size / TotalSize
        self.TxtRight.text = localize('下载资源中...(_pro/_total) (_speed/s)', { _pro = Utils.HumanReadableBytes(checkNumber(size), false),
                                                                  _total = Utils.HumanReadableBytes(checkNumber(TotalSize), false),
                                                                                 _speed = Utils.HumanReadableBytes(checkNumber(speed)) })
        self.Slider.value = checkNumber(Progress)
        self.LoadingValue.text = string.format('%.2f%%', Progress * 100)
        local proInt = math.floor(Progress * 100)
        if proInt % 20 == 0 then
            if not progressMap[tostring(proInt)] then
                progressMap[tostring(proInt)] = proInt
                xRecord.record('14-005', string.format('download_progress_small_%s%%', proInt))
            end
        end
    end
    download:SetFinishCallback(function(state)
        xRecord.record('14-006', 'download_progress_small_completed')
        ---@type Engine.Lib.Updater.DownloadState
        local mState = state
        if mState.IsError then
            xRecord.record('14-010', checkString(mState.Error.Message).. "\n" .. checkString(mState.Error.StackTrace))
            ---直接显示错误
            self.TxtLeft.text = mState.Error.Message
        else
            ----正常的下载完成
            if not download.IsFinished then
                download:Finish()
            else
                download.ProgressCallback = nil
                download:SetFinishCallback(nil)
            end
            KTool.SetActive(self.ActiveNode.gameObject, true)
            ---强制结束
            KTool.SetActive(self.TxtRight.gameObject, false)
            self.TxtLeft.text = localize('资源下载完成，开始解压...')
            self.LoadingValue.text = string.format('%d%%', 100)
        end
    end)
    property = downloadMemberInfo:GetProperty("OnCheckPercentCallback")
    if isNotNull(property) then
        local verifyProgress = 0
        download.OnCheckPercentCallback = function(percent)
            local proInt = math.floor(percent)
            if proInt >= verifyProgress then
                local currentProgress = verifyProgress
                while proInt >= verifyProgress do
                    currentProgress = verifyProgress
                    verifyProgress = verifyProgress + 20
                end
                self.TxtLeft.text = localize("文件校验中...")
                self.LoadingValue.text = string.format('%d%%', verifyProgress)
            end
        end
    end
    property = downloadMemberInfo:GetProperty("OnLastMd5CheckCallback")
    if isNotNull(property) then
        download.OnLastMd5CheckCallback = function()
            xRecord.record('14-022', string.format('verify_progress_%s%%', 75))
            self.TxtLeft.text = localize("文件合并中，请耐心等待...")
            self.LoadingValue.text = string.format('%d%%', 75)
        end
    end
    property = downloadMemberInfo:GetProperty("OnLastMargeFileCallback")
    if isNotNull(property) then
        download.OnLastMargeFileCallback = function()
            self.TxtLeft.text = localize("文件合并中，请耐心等待...")
        end
    end
    property = downloadMemberInfo:GetProperty("OnFailCallback")
    if isNotNull(property) then
        download.OnFailCallback = function(error)
            if error == Constants.DownloadErrorType.INSUFFICIENT_DISK_SPACE_ERROR then
                self.TxtLeft.text = localize("空间不足,请清理空间")
            elseif error == Constants.DownloadErrorType.UNKNOWN then
                self.TxtLeft.text = localize("未知错误")
            elseif error == Constants.DownloadErrorType.FILE_MERGE_ERROR then
                self.TxtLeft.text = localize("文件错误")
            elseif error == Constants.DownloadErrorType.FILE_CHECK_ERROR then
                self.TxtLeft.text = localize("文件检测错误")
            elseif error == Constants.DownloadErrorType.NETWORK_ERROR then
                self.TxtLeft.text = localize("网络错误")
            elseif error == Constants.DownloadErrorType.BLOCK_ERROR then
                self.TxtLeft.text = localize("下载错误，修正中")
            end
        end
    end
    local vendorPath = PathUtility.Combine(ResourceModule.AppDataPath, ResourceModule.ProductSplitPath)
    local decompressState = DecompressState(vendorPath, download)
    decompressState.OnDecompressProgressAction = function()
        ---解压文件显示
        self.Slider.value = checkNumber(decompressState.Progress)
        self.LoadingValue.text = string.format('%.2f%%', decompressState.Progress * 100)
        self.TxtLeft.text = string.format('解压中...%d%%', math.floor(decompressState.Progress * 100))
    end
    decompressState.IsDeleteZip = false
    decompressState:SetFinishCallback(function()
        if decompressState.IsError then
            xRecord.record('14-010', checkString(decompressState.Error.Message).. "\n" .. checkString(decompressState.Error.StackTrace))
            ----解压出错的情况下，清理下下载目录
            local downloadPath = PathUtility.Combine(ResourceModule.AppDataPath, "Download")
            if Exists(downloadPath) then
                ---更新写入的路径
                PathUtility.Clean(downloadPath)
            end
            if not Exists(downloadPath) then
                Directory.CreateDirectory(downloadPath)
            end
        end
    end)

    local verifyPackageState = VerifyPackageState(download)
    ---@type Engine.Lib.Updater.Updater
    local updater = Updater({ download, verifyPackageState, decompressState })
    updater.FinishCallback = function(update)
        ---更新完成进入游戏
        if updater.IsError then
            xRecord.record('14-010',  tostring(updater.Error.Message) .. "\n" .. checkString(updater.Error.StackTrace))
            ---更新出现错误了
            self.TxtLeft.text = tostring(updater.Error.Message)
        else
            ---设置记录
            PlayerPrefsUtility.SetEncryptedString(SmallPackageDownloaded, CS.UnityEngine.Application.version)
            PlayerPrefsUtility.Save()
            local downloadPath = PathUtility.Combine(ResourceModule.AppDataPath, "Download")
            if Exists(downloadPath) then
                ---更新写入的路径
                PathUtility.Clean(downloadPath)
            end
            if not Exists(downloadPath) then
                Directory.CreateDirectory(downloadPath)
            end
            CS.Engine.UI.UIModule.OpenDialog({ id = GameInitScene }, { { id = 12 } }, false)
        end
    end
    ---开启线程来检测状态
    CS.Engine.Lib.AppEngine._Instance:StartCoroutine(updater:StartEnumerator())
    while not updater.IsDone do
        cs_coroutine.yield_return(Yielders.EndOfFrame)
    end
end

function CatDownloader:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller:StartCoroutine(util.cs_generator(function()
            ----开启一个功程
            while self.starting do
                cs_coroutine.yield_return(Yielders.GetWaitForSeconds(IMAGE_SWITCH_INTERVAL))
                ---执行切换背景图
                local preIndex = self.position
                local bgImagePreKey = string.format("%s%d", LOADING_BG_PREFIX, preIndex)
                local dotImagePreKey = string.format("%s%d", LOADING_DOT_PREFIX, preIndex)
                self.position = preIndex + 1
                if self.position > IMAGE_COUNT then
                    self.position = 1
                end
                ---加载下一张图，然后切换的逻辑
                local pos = self:GetPosition(self.position)
                local url = string.format('%s%d.png', IMAGE_PREFIX, pos)
                local loader = ResourceModule.LoadBundleAsync(url)
                while not loader.IsCompleted do
                    cs_coroutine.yield_return()
                end
                if not loader.IsSuccess then
                    loader:Release(true)
                else
                    self.loaders[url] = loader
                    ---更新图片
                    local bgImageKey = string.format("%s%d", LOADING_BG_PREFIX, self.position)
                    local nexImageTrans = self[bgImageKey].transform:Find(string.format("ImgBg%d", self.position))
                    local preImage = self[bgImagePreKey]
                    if not isNull(nexImageTrans) then
                        ---@type UnityEngine.UI.RawImage
                        local rawImage = KTool.GetOrAddComponent(nexImageTrans.gameObject, typeof(RawImage))
                        rawImage.texture = loader.ResultObject
                    end
                    ----@type UnityEngine.CanvasGroup
                    local nextGroup = KTool.GetComponent(self[bgImageKey].gameObject, typeof(CanvasGroup))
                    nextGroup.alpha = 0
                    KTool.SetActive(self[bgImageKey].gameObject, true)
                    local preGroup = KTool.GetComponent(preImage.gameObject, typeof(CanvasGroup))
                    local sequence = DOTween.Sequence()
                    sequence:Append(nextGroup:DOFade(1, IMAGE_SWITCH_ANIMATION_INTERVAL))
                    sequence:Join(preGroup:DOFade(0, IMAGE_SWITCH_ANIMATION_INTERVAL))
                    sequence:PlayForward()
                    ---更新选中条
                    local dotImageKey = string.format("%s%d", LOADING_DOT_PREFIX, self.position)
                    ----@type Game.Native.Common.UISwitchImage
                    local preDotImage = KTool.GetComponent(self[dotImagePreKey].gameObject, typeof(UISwitchImage))
                    ----@type Game.Native.Common.UISwitchImage
                    local nextDotImage = KTool.GetComponent(self[dotImageKey].gameObject, typeof(UISwitchImage))
                    if preDotImage and nextDotImage then
                        preDotImage.Status = 2
                        nextDotImage.Status = 1
                    end
                    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(IMAGE_SWITCH_ANIMATION_INTERVAL + 0.2))
                end
            end
        end))
        ----开始请求下载的逻辑
        KTool.SetActive(self.TxtLeft.gameObject, true)
        self.TxtLeft.text = localize("检测更新中...")
        local vendorPath = PathUtility.Combine(ResourceModule.AppDataPath, ResourceModule.ProductSplitPath)
        --更新写入的路径
        if not Exists(vendorPath) then
            Directory.CreateDirectory(vendorPath)
        end
        ---资源版本号信息是否存在
        local preVersion = PlayerPrefsUtility.GetEncryptedString(SmallPackageDownloaded, "")
        if string.isEmpty(preVersion) then
            preVersion = CS.UnityEngine.Application.version
        end
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(4))
        cs_coroutine.yield_return(self:RequestAsync(preVersion))
    end))
    return coWait
end

function CatDownloader:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        KTool.SetActive(self.LoadingSlider.gameObject, false)
    end))
    return coWait
end

function CatDownloader:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.starting = false
        if not isNull(self.co) then
            self.controller:StopCoroutine(self.co)
        end
        if self.loaders then
            for i, v in pairs(self.loaders) do
                v:Release(true)
            end
            self.loaders = nil
        end
        self.co = nil
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return CatDownloader